import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import '../styles/components/Header.scss';
import siteData from '../data/siteData.json';

const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const { siteInfo, navigation } = siteData;

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  return (
    <header className="header">
      <div className="container">
        <div className="header__content">
          <Link to="/" className="header__logo">
            <h1>{siteInfo.name}</h1>
          </Link>

          <button 
            className={`header__menu-btn ${isMenuOpen ? 'active' : ''}`}
            onClick={toggleMenu}
            aria-label="Menu"
          >
            <span></span>
            <span></span>
            <span></span>
          </button>

          <nav className={`header__nav ${isMenuOpen ? 'active' : ''}`}>
            <ul>
              <li><Link to="/" onClick={() => setIsMenuOpen(false)}>{navigation.home}</Link></li>
              <li><Link to="/services" onClick={() => setIsMenuOpen(false)}>{navigation.services}</Link></li>
              <li><Link to="/about" onClick={() => setIsMenuOpen(false)}>{navigation.about}</Link></li>
              <li><Link to="/contact" onClick={() => setIsMenuOpen(false)}>{navigation.contact}</Link></li>
            </ul>
          </nav>
        </div>
      </div>
    </header>
  );
};

export default Header;
